var TBL_TITLE = 'Bảng giải thích từng lệnh và kết quả';
var MAX = 20; /* số câu lab tối đa mỗi phần (k = ceil(N/MAX)) */

function isTbl(t) { return t && t.title === TBL_TITLE; }
function split(n, k) { var a = [], i, b = Math.floor(n / k), r = n % k; for (i = 0; i < k; i++) a.push(b + (i < r ? 1 : 0)); return a; }
function runHint(sh, hint) {
  var buf = '';
  hint.split('\n').forEach(function (line) {
    buf = buf === '' ? line : buf + '\n' + line;
    if (!sh.isComplete(buf)) return;
    sh.run(buf); buf = '';
  });
}
function tableFor(lid, lo, hi, part, total) {
  if (!DATA[lid]) return null;
  var tbl = [['Lệnh', 'Giải thích', 'Kết quả khi chạy']];
  DATA[lid].forEach(function (r) {
    if (r[0] - 1 >= lo && r[0] - 1 < hi) tbl.push(['`' + r[1] + '`', r[2], r[3]]);
  });
  return { tag: 'Bảng lệnh', title: TBL_TITLE + (total > 1 ? ' (phần ' + part + ')' : ''), body: [{ tbl: tbl }] };
}

var IDS = C.lessons.filter(function (l) { return l.lab && l.lab.items && l.lab.items.length >= 28; }).map(function (l) { return l.id; });
IDS.forEach(function (lid) {
  var idx = -1;
  C.lessons.forEach(function (l, i) { if (l.id === lid) idx = i; });
  if (idx < 0) return;
  var L = C.lessons[idx];
  var items = L.lab.items, N = items.length;
  var k = Math.ceil(N / MAX);
  if (k <= 1) return;
  var sizes = split(N, k);
  var theoryAll = L.theory.filter(function (t) { return !isTbl(t); });
  var tsizes = split(theoryAll.length, k);
  var origSetup = L.lab.setup, origHost = L.lab.host, origUser = L.lab.user;
  var allQuiz = L.quiz || [], allDebugs = L.debugs || [];
  var qsz = split(allQuiz.length, k), dsz = split(allDebugs.length, k);
  var qpos = 0, dpos = 0;
  var parts = [], start = 0, tstart = 0;
  for (var p = 0; p < k; p++) {
    var lo = start, hi = start + sizes[p];
    var th = theoryAll.slice(tstart, tstart + tsizes[p]);
    tstart += tsizes[p];
    var tb = tableFor(lid, lo, hi, p + 1, k);
    if (tb) th.push(tb);
    parts.push({ lo: lo, hi: hi, theory: th, quiz: allQuiz.slice(qpos, qpos + qsz[p]), debugs: allDebugs.slice(dpos, dpos + dsz[p]) });
    qpos += qsz[p]; dpos += dsz[p];
    start = hi;
  }
  // part 1 keeps the original lesson object
  var base = { group: L.group, dek: L.dek, title: L.title, short: L.short };
  parts.forEach(function (pt, p) {
    var its = items.slice(pt.lo, pt.hi);
    var replay = items.slice(0, pt.lo).map(function (it) { return it.hint; });
    var setup = function (s) {
      if (origSetup) origSetup(s);
      replay.forEach(function (h) { runHint(s, h); });
    };
    if (p === 0) {
      L.theory = pt.theory; L.quiz = pt.quiz; L.debugs = pt.debugs;
      L.lab = { host: origHost, user: origUser, setup: origSetup, items: its };
      L.short = base.short + ' (1/' + k + ')';
      return;
    }
    var nl = {
      id: lid + '-' + (p + 1), group: base.group, short: base.short + ' (' + (p + 1) + '/' + k + ')',
      title: base.title + ' — phần ' + (p + 1) + '/' + k, dek: base.dek,
      theory: pt.theory, quiz: pt.quiz, debugs: pt.debugs,
      lab: { host: origHost, user: origUser, setup: setup, items: its }
    };
    var prev = p === 1 ? lid : lid + '-' + p;
    C.insertAfter(prev, nl);
  });
  // quiz and debugs stay with part 1 (already on L); fix part-1 setup not needed
  L.lab.setup = origSetup;
  // rebuild part-1 theory cleanly (table already attached to parts[0].theory)
});
